import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.Function;import java.io.*;public class SamplerOwners extends GhidraScript{public void run()throws Exception{String[]a=getScriptArgs();try(PrintWriter w=new PrintWriter(a[0])){for(int i=1;i<a.length;i++){Function f=getFunctionContaining(toAddr(a[i]));w.println(a[i]+"\t"+(f==null?"NONE":f.getEntryPoint()+"\t"+f.getBody().getMaxAddress()));}}}}